void kernel_covariance(num_t float_n, auto data, auto cov, auto mean) {
	// data: k x j  (N samples, M features)
	// cov:  i x j  (M x M)
	// mean: j      (M)
	using namespace noarr;

	// view of data where the feature dimension is called 'i'
	// (for cov's row index); data_i: k x i
	auto data_i = data ^ noarr::rename<'j', 'i'>();

	// Precompute reciprocals once to replace many divisions with multiplications.
	const num_t inv_n  = (num_t)1.0 / float_n;
	const num_t inv_n1 = (num_t)1.0 / (float_n - (num_t)1.0);

#pragma scop
	// 1) mean[j] = (1/n) * sum_k data[k][j]
	//
	// Original order was: for each j, sum over k.
	// We now do: for each k (sample), walk all j (features) in one contiguous row
	// and accumulate into mean[j]. For a fixed j, the order of additions over k
	// is still strictly increasing k, so floating‑point results are bit‑identical.

	// 1a) initialize mean[j] = 0
	traverser(mean).for_each([&](auto sm) {
		mean[sm] = (num_t)0;
	});

	// 1b) accumulate sums over samples, streaming rows of `data`
	traverser(data, mean).template for_dims<'k'>([&](auto tk) {
		// tk has 'k' fixed; for_each iterates remaining dim 'j'
		tk.for_each([&](auto s) {
			// s contains 'k' and 'j'; 'k' is ignored when indexing mean
			mean[s] += data[s];
		});
	});

	// 1c) scale by 1/n
	traverser(mean).for_each([&](auto sm) {
		mean[sm] *= inv_n;
	});

	// 2) data[k][j] -= mean[j]
	//
	// Traverse sample-major, feature-minor: each row of `data` is contiguous
	// and we update it in-place.
	traverser(data, mean).template for_dims<'k'>([&](auto tk) {
		tk.for_each([&](auto s) {
			data[s] -= mean[s]; // mean ignores the 'k' index in s
		});
	});

