			// tki has k and i fixed, j still free
			auto si = tki.state();        // contains 'k' and 'i'
			const num_t x_ki = data_i[si]; // data_i[k][i], reused for all j

			tki.template for_dims<'j'>([&](auto tkij) {
				auto s = tkij.state(); // contains 'k', 'i', 'j'
				auto [i_idx, j_idx] = get_indices<'i', 'j'>(s);

				// enforce j >= i (upper triangle including diagonal)
				if (j_idx < i_idx)
					return;

				// cov[i][j] += data[k][i] * data[k][j]
				cov[s] += x_ki * data[s]; // data ignores 'i' index in s
			});
		});
	});

	// 3c) normalize and enforce symmetry:
	//     cov[i][j] = cov[j][i] = sum_k data[k][i]*data[k][j] / (n-1)
	traverser(cov).template for_dims<'i'>([&](auto ti) {
		ti.template for_dims<'j'>([&](auto tij) {
			auto s_ij = tij.state();
			auto [i_idx, j_idx] = get_indices<'i', 'j'>(s_ij);

			// work only on upper triangle (j >= i)
			if (j_idx < i_idx)
				return;

