	//     this walks each sample's feature vector contiguously in memory.
	traverser(data, mean).template for_dims<'k'>([&](auto tk) {
		tk.template for_each<'j'>([&](auto s_kj) {
			// `s_kj` contains 'k' and 'j'; mean ignores 'k'.
			mean[s_kj] += data[s_kj];
		});
	});

	// 1c) Scale by 1 / float_n in a separate pass to simplify the accumulation.
	traverser(mean).for_each([&](auto sj) {
		mean[sj] *= inv_float_n;
	});

