	const num_t inv_float_n = num_t(1) / float_n;
	const num_t inv_float_n_minus_one = num_t(1) / (float_n - num_t(1));

#pragma scop
	// ------------------------------------------------------------------
	// 1) mean[j] = (1/n) * sum_k data[k][j]
	// ------------------------------------------------------------------

	// 1a) initialize mean[j] = 0
	traverser(mean).for_each([&](auto s_j) {
		mean[s_j] = num_t(0);
	});

