	//     outer loop over samples 'k', inner loop over features 'j'.
	//     This walks "rows" of data (k fixed, j contiguous).
	traverser(data, mean).template for_dims<'k'>([&](auto tk) {
		tk.template for_each<'j'>([&](auto s_kj) {
			// s_kj has indices 'k' and 'j'; 'k' is ignored when indexing mean
			mean[s_kj] += data[s_kj];
		});
	});

	// 1c) scale by 1 / n
	traverser(mean).for_each([&](auto s_j) {
		mean[s_j] *= inv_float_n;
	});

	// ------------------------------------------------------------------
	// 2) Center data in-place: data[k][j] -= mean[j]
	// ------------------------------------------------------------------
	// Again traverse row-major: outer 'k', inner 'j'.
	traverser(data, mean).template for_dims<'k'>([&](auto tk) {
		tk.template for_each<'j'>([&](auto s_kj) {
			data[s_kj] -= mean[s_kj]; // mean ignores the 'k' index
		});
	});

