	// 3) covariance
	//    cov = (1/(n-1)) * data^T * data
	//
	//    We compute only the upper triangle (j >= i) and then mirror it.
	//    Algorithm:
	//      cov[:] = 0
	//      for k in 0..N-1:
	//        for i in 0..M-1:
	//          x_ki = data[k][i]
	//          for j in i..M-1:
	//            cov[i][j] += x_ki * data[k][j]
	//      cov[i][j] *= 1/(n-1)
	//      cov[j][i] = cov[i][j]
	//
