	// This makes explicit that we conceptually traverse rows (i) first.
	auto cov_by_i = traverser(cov).order(hoist<'i'>());

	// 3b) accumulate outer products sample-by-sample
	//
	// Outer traverser over samples 'k'; this follows the data layout,
	// giving good locality over data rows.
	traverser(data).template for_dims<'k'>([&](auto tk) {
		// State containing just the current sample index 'k'
		auto s_k = tk.state();

		// For each row i of the covariance matrix
		cov_by_i.template for_dims<'i'>([&](auto ti) {
			auto s_i = ti.state();
			std::size_t i_idx = get_index<'i'>(s_i);

			// Pre-load data[k][i] once for this (k, i) pair and reuse it
			auto s_ki = s_k + idx<'j'>(i_idx); // state with 'k' and 'j' = i
			const num_t x_ki = data[s_ki];

			// For each column j in this row (upper triangle only)
			ti.template for_dims<'j'>([&](auto tij) {
				auto s_ij = tij.state(); // indices 'i' and 'j'
				std::size_t j_idx = get_index<'j'>(s_ij);

				// Skip lower triangle; we only accumulate j >= i
				if (j_idx < i_idx)
					return;

				// data[k][j]
				auto s_kj = s_k + idx<'j'>(j_idx);

				// Accumulate contribution of sample k to cov[i][j]
				cov[s_ij] += x_ki * data[s_kj];
			});
		});
	});

	// 3c) normalize and symmetrize covariance matrix
	cov_by_i.template for_dims<'i'>([&](auto ti) {
		ti.template for_dims<'j'>([&](auto tij) {
			auto s_ij = tij.state();
			auto [i_idx, j_idx] = get_indices<'i', 'j'>(s_ij);

			// Only process upper triangle
			if (j_idx < i_idx)
				return;

			// Normalize cov[i][j]
			cov[s_ij] *= inv_float_n_minus_one;

			// Enforce symmetry: cov[j][i] = cov[i][j]
			auto s_ji = idx<'i', 'j'>(j_idx, i_idx);
			cov[s_ji] = cov[s_ij];
		});
	});
#pragma endscop
}

