//       cov[i][j] = (1/(n-1)) * sum_k (x[k][i] - mean[i]) * (x[k][j] - mean[j])
[[gnu::flatten, gnu::noinline]]
void kernel_covariance(num_t float_n, auto data, auto cov, auto mean) {
	// data: k x j  (N samples, M features)
	// cov:  i x j  (M x M)
	// mean: j      (M)
	using namespace noarr;

	const num_t one      = (num_t)1.0;
	const num_t inv_n    = one / float_n;
	const num_t inv_n_1  = one / (float_n - one);

	// number of features (M) – length in 'j'
	const std::size_t m_len = data | get_length<'j'>();

	// Temporary buffer for one centered sample (one row of `data`).
	// We allocate it once per kernel call, outside the SCoP region,
	// and reuse it for all samples.
	std::vector<num_t> row(m_len);

#pragma scop
	// ----------------------------------------------------------------------
	// 1) mean[j] = (1/n) * sum_k data[k][j]
	// ----------------------------------------------------------------------

	// 1a) initialize mean[j] = 0
	traverser(mean).for_each([&](auto sj) {
		mean[sj] = (num_t)0;
	});

	// 1b) accumulate column sums in a k-major, j-minor order
	//     This matches the k x j layout of `data`, improving locality.
	traverser(data, mean).template for_dims<'k'>([&](auto tk) {
		tk.template for_each<'j'>([&](auto s_kj) {
			mean[s_kj] += data[s_kj];
		});
	});

	// 1c) scale by 1/n
	traverser(mean).for_each([&](auto sj) {
		mean[sj] *= inv_n;
	});

