	// 2) data[k][j] -= mean[j]   (center the data)
	// ----------------------------------------------------------------------
	// Again use k-major, j-minor traversal to keep accesses contiguous.
	traverser(data, mean).template for_dims<'k'>([&](auto tk) {
		tk.template for_each<'j'>([&](auto s_kj) {
			data[s_kj] -= mean[s_kj]; // mean uses only 'j' from the state
		});
	});

