	// 3) covariance
	//
	// We compute:
	//   cov[i][j] = sum_k data[k][i] * data[k][j] / (float_n - 1)
	//
	// Optimization strategy:
	//   - First, set cov[i][j] = 0 for all i,j.
	//   - For each sample k:
	//       * load the entire centered row data[k][j] into a contiguous
	//         temporary buffer `row[j]`
	//       * form the outer product row * row^T and accumulate into cov
	//         (only for j >= i, then mirror to cov[j][i])
	//   - Finally, scale all cov[i][j] by 1/(n-1).
	//
	// This "outer-product" formulation reads each sample row from `data`
	// exactly once and then reuses it from the L1-resident `row` buffer,
	// significantly reducing data traffic compared to the original
	// i-j-k formulation, while preserving the mathematical result
	// (up to floating-point associativity).
	// ----------------------------------------------------------------------

	// 3a) initialize covariance matrix to zero
	traverser(cov).for_each([&](auto s_ij) {
		cov[s_ij] = (num_t)0;
	});

	// 3b) accumulate outer products over all samples k
	traverser(data).template for_dims<'k'>([&](auto tk) {
		// Copy centered row k of `data` into `row` (j-minor, contiguous)
		tk.template for_each<'j'>([&](auto s_kj) {
			auto j_idx = get_index<'j'>(s_kj);
			row[j_idx] = data[s_kj];
		});

		// For the current row `row`, accumulate row * row^T into `cov`.
		// We keep i-major, j-minor traversal for `cov` so that we always
		// update contiguous elements along 'j'.
		traverser(cov).template for_dims<'i'>([&](auto ti) {
			auto s_i   = ti.state();
			auto i_idx = get_index<'i'>(s_i);

			const num_t x_i = row[i_idx];

			ti.template for_each<'j'>([&](auto s_ij) {
				auto j_idx = get_index<'j'>(s_ij);

				// Only process upper triangle (including diagonal)
				if (j_idx < i_idx)
					return;

				const num_t product = x_i * row[j_idx];

				// Accumulate into cov[i][j]
				cov[s_ij] += product;

				// Maintain symmetry: cov[j][i] = cov[i][j]
				if (j_idx != i_idx) {
					auto s_ji = noarr::idx<'i', 'j'>(j_idx, i_idx);
					cov[s_ji] += product;
				}
			});
		});
